/**
 * Express 4 compatibility for the apps that nodes register routes on
 * (RED.httpNode and RED.httpAdmin).
 *
 * Many third party nodes were written against Express 4. Express 5 rejects
 * some of their route paths at registration time (which stops the whole node
 * module from loading) and removes some request/response methods they call.
 * This module keeps those nodes working and logs a one-time deprecation
 * warning for each Express 4 pattern it has to translate, so node authors can
 * update before the compatibility layer is removed.
 *
 * What it handles:
 *  - unnamed wildcards in paths ("/my-node/*"), with req.params[0] restored
 *    as the matched string, as in Express 4
 *  - optional parameters ("/items/:id?")
 *  - res.send(status), res.send(body, status), res.json(obj, status),
 *    res.jsonp(obj, status), res.sendfile(), req.param()
 *  - app._router (renamed to app.router in Express 5), with layer.regexp
 *    restored on router layers for nodes that look up their routes by it
 *  - writes to req.query (a read-only, re-parsed getter in Express 5)
 *
 * @mixin @node-red/runtime_express4compat
 */

const { log } = require("@node-red/util");

const ROUTE_METHODS = ["all", "get", "post", "put", "delete", "patch", "options", "head", "use"];
const WILDCARD_PREFIX = "__express4_wildcard_";
const warned = new Set();

function warnOnce(key, message) {
    if (!warned.has(key)) {
        warned.add(key);
        log.warn("[express4-compat] " + message);
    }
}

/**
 * Translate an Express 4 route path into Express 5 syntax.
 * @param {*} path - the route path as registered
 * @return {{path: *, wildcards: Number}} the translated path and the number of
 *         unnamed wildcards it contained
 * @memberof @node-red/runtime_express4compat
 */
function convertPath(path) {
    if (typeof path !== "string") {
        return { path, wildcards: 0 };
    }
    let wildcards = 0;
    // "/items/:id?" -> "/items{/:id}"
    let converted = path.replace(/\/:([A-Za-z_$][\w$]*)\?/g, "{/:$1}");
    // "/my-node/*" -> "/my-node/{*__express4_wildcard_0}"
    // (braces make it optional, so "/my-node/" still matches, as in Express 4)
    converted = converted.replace(/\*(?![A-Za-z_$])/g, function() {
        return "{*" + WILDCARD_PREFIX + (wildcards++) + "}";
    });
    return { path: converted, wildcards };
}

function restoreWildcardParams(count) {
    return function express4WildcardParams(req, res, next) {
        for (let i = 0; i < count; i++) {
            const value = req.params[WILDCARD_PREFIX + i];
            req.params[i] = Array.isArray(value) ? value.join("/") : (value === undefined ? "" : value);
        }
        next();
    };
}

/**
 * Build the regular expression Express 4 would have stored on a router layer
 * (layer.regexp) for a path. Express 5 layers no longer have one, but some
 * nodes inspect router stacks and compare layer.regexp to find their routes.
 * This follows path-to-regexp 0.1, which Express 4 used.
 * @param {*} path - the path as registered
 * @param {Boolean} end - true for routes (app.get etc), false for app.use
 * @return {RegExp|undefined}
 * @memberof @node-red/runtime_express4compat
 */
function express4LayerRegexp(path, end) {
    if (path instanceof RegExp) {
        return path;
    }
    if (Array.isArray(path)) {
        return new RegExp(path.map(function(p) { return express4LayerRegexp(p, end).source; }).join("|"), "i");
    }
    if (typeof path !== "string") {
        return undefined;
    }
    let backtrack = "";
    let pos = 0;
    let source = path.replace(/\\.|(\/)?(\.)?:(\w+)(\(.*?\))?(\*)?(\?)?|[.*]|\/\(/g,
        function(match, slash, format, key, capture, star, optional, offset) {
            if (match[0] === "\\") {
                backtrack += match;
                pos += 2;
                return match;
            }
            if (match === ".") {
                backtrack += "\\.";
                pos += 1;
                return "\\.";
            }
            if (slash || format) {
                backtrack = "";
            } else {
                backtrack += path.slice(pos, offset);
            }
            pos = offset + match.length;
            if (match === "*") {
                backtrack = "";
                return "(.*)";
            }
            if (match === "/(") {
                backtrack += "/";
                return "/(?:";
            }
            slash = slash || "";
            format = format ? "\\." : "";
            optional = optional || "";
            capture = capture ?
                capture.replace(/\\.|\*/, function(m) { return m === "*" ? "(.*)" : m; }) :
                (backtrack ? "((?:(?!/|" + backtrack + ").)+?)" : "([^/" + format + "]+?)");
            backtrack = "";
            return "(?:" + format + slash + capture + (star ? "((?:[/" + format + "].+?)?)" : "") + ")" + optional;
        });
    source += source[source.length - 1] === "/" ? "?" : "/?";
    if (end) {
        source += "$";
    } else if (source[source.length - 1] !== "/") {
        source += "(?=/|$)";
    }
    const regexp = new RegExp("^" + source, "i");
    regexp.fast_star = path === "*";
    regexp.fast_slash = path === "/" && !end;
    return regexp;
}

function addLegacyRegexp(layer, path, end) {
    if (!layer || layer.regexp !== undefined) {
        return;
    }
    const regexp = express4LayerRegexp(path, end);
    if (regexp) {
        Object.defineProperty(layer, "regexp", { value: regexp, writable: true, configurable: true });
    }
    if (layer.route && Array.isArray(layer.route.stack)) {
        layer.route.stack.forEach(function(inner) { addLegacyRegexp(inner, "/", true); });
    }
}

function wrapRouteMethods(app) {
    ROUTE_METHODS.forEach(function(method) {
        const original = app[method];
        if (typeof original !== "function") {
            return;
        }
        app[method] = function(path) {
            // app.get("setting") reads a setting rather than adding a route
            if (method === "get" && arguments.length === 1) {
                return original.apply(this, arguments);
            }
            const router = this.router;
            const before = router.stack.length;
            const isRoute = method !== "use";
            if (typeof path !== "string" && !Array.isArray(path) && !(path instanceof RegExp)) {
                // app.use(fn) without a path
                const result = original.apply(this, arguments);
                for (let i = before; i < router.stack.length; i++) { addLegacyRegexp(router.stack[i], "/", false); }
                return result;
            }
            if (path instanceof RegExp) {
                const result = original.apply(this, arguments);
                for (let i = before; i < router.stack.length; i++) { addLegacyRegexp(router.stack[i], path, isRoute); }
                return result;
            }
            const handlers = Array.prototype.slice.call(arguments, 1);
            const paths = Array.isArray(path) ? path : [path];
            let wildcards = 0;
            const convertedPaths = paths.map(function(p) {
                const result = convertPath(p);
                wildcards = Math.max(wildcards, result.wildcards);
                if (result.path !== p) {
                    warnOnce("path:" + p, `Route '${p}' uses Express 4 path syntax. It has been registered as '${result.path}'. Update the node that registers it to Express 5 syntax.`);
                }
                return result.path;
            });
            const args = [Array.isArray(path) ? convertedPaths : convertedPaths[0]];
            if (wildcards > 0) {
                args.push(restoreWildcardParams(wildcards));
            }
            const result = original.apply(this, args.concat(handlers));
            for (let i = before; i < router.stack.length; i++) {
                // what Express 4 would have stored, built from the original path
                addLegacyRegexp(router.stack[i], path, isRoute);
            }
            return result;
        };
    });
}

function express4RequestResponse(req, res, next) {
    // Express 5 re-parses req.query on every access, so writes to it are lost
    const query = req.query;
    Object.defineProperty(req, "query", { value: query, writable: true, enumerable: true, configurable: true });

    if (typeof req.param !== "function") {
        req.param = function(name, defaultValue) {
            warnOnce("req.param", "req.param() was removed in Express 5. Use req.params, req.body or req.query.");
            const sources = [this.params || {}, this.body || {}, this.query || {}];
            for (const source of sources) {
                if (Object.prototype.hasOwnProperty.call(source, name) && source[name] != null) {
                    return source[name];
                }
            }
            return defaultValue;
        };
    }

    const send = res.send;
    res.send = function(body) {
        if (arguments.length === 1 && typeof body === "number") {
            warnOnce("res.send(status)", "res.send(status) was removed in Express 5. Use res.sendStatus(status).");
            return this.sendStatus(body);
        }
        if (arguments.length === 2) {
            if (typeof arguments[1] === "number") {
                warnOnce("res.send(body,status)", "res.send(body, status) was removed in Express 5. Use res.status(status).send(body).");
                this.status(arguments[1]);
                return send.call(this, arguments[0]);
            }
            if (typeof arguments[0] === "number") {
                warnOnce("res.send(status,body)", "res.send(status, body) was removed in Express 5. Use res.status(status).send(body).");
                this.status(arguments[0]);
                return send.call(this, arguments[1]);
            }
        }
        return send.apply(this, arguments);
    };

    ["json", "jsonp"].forEach(function(method) {
        const original = res[method];
        res[method] = function(obj) {
            if (arguments.length === 2) {
                const statusFirst = typeof arguments[0] === "number";
                const statusLast = typeof arguments[1] === "number";
                if (statusLast || statusFirst) {
                    warnOnce("res." + method, `res.${method}(obj, status) was removed in Express 5. Use res.status(status).${method}(obj).`);
                    this.status(statusLast ? arguments[1] : arguments[0]);
                    return original.call(this, statusLast ? arguments[0] : arguments[1]);
                }
            }
            return original.apply(this, arguments);
        };
    });

    if (typeof res.sendfile !== "function") {
        res.sendfile = function() {
            warnOnce("res.sendfile", "res.sendfile() was removed in Express 5. Use res.sendFile().");
            return this.sendFile.apply(this, arguments);
        };
    }
    next();
}

/**
 * Add Express 4 compatibility to an Express 5 app.
 * @param {Object} app - an Express 5 application
 * @return {Object} the same app
 * @memberof @node-red/runtime_express4compat
 */
function apply(app) {
    if (!Object.prototype.hasOwnProperty.call(app, "_router")) {
        Object.defineProperty(app, "_router", {
            configurable: true,
            get: function() {
                warnOnce("app._router", "app._router was renamed to app.router in Express 5.");
                return this.router;
            }
        });
    }
    wrapRouteMethods(app);
    app.use(express4RequestResponse);
    return app;
}

module.exports = {
    apply,
    convertPath,
    express4LayerRegexp,
    _reset: function() { warned.clear(); }
};
